"use client";

import { Radio } from "@base-ui/react/radio";
import { RadioGroup as Group } from "@base-ui/react/radio-group";
import { LayoutGroup, motion } from "motion/react";
import { useId } from "react";
import type { ComponentProps, ReactNode } from "react";

import { FluidHoverArea } from "@/components/ui/fluid-hover-area";
import { useReducedMotion } from "@/hooks/use-reduced-motion";
import { motionPresets } from "@/lib/motion";
import { useShape } from "@/lib/shape-context";
import { useSize } from "@/lib/size-context";
import { cn } from "@/lib/utils";

export const RadioGroup = ({
  className,
  ...props
}: ComponentProps<typeof Group>) => {
  const shape = useShape();
  const id = useId();
  return (
    <LayoutGroup id={id}>
      <Group
        render={<FluidHoverArea itemSelector="[data-slot=radio-item]" />}
        className={cn("p-1", shape, className)}
        {...props}
      />
    </LayoutGroup>
  );
};
export const RadioItem = ({
  label,
  description,
  className,
  ...props
}: ComponentProps<typeof Radio.Root> & {
  label: ReactNode;
  description?: ReactNode;
}) => {
  const id = useId();
  const size = useSize();
  const reduced = useReducedMotion();
  const shape = useShape();
  return (
    <Radio.Root
      data-slot="radio-item"
      aria-labelledby={`${id}-label`}
      aria-describedby={description ? `${id}-description` : undefined}
      className={cn(
        "relative flex w-full cursor-pointer items-center text-left outline-none transition-colors duration-(--motion-fast) data-[checked]:bg-foreground/5 focus-visible:ring-2 focus-visible:ring-ring data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50",
        size.px,
        size.gap,
        size.text,
        shape,
        description ? "py-2" : size.control,
        className
      )}
      {...props}
    >
      <span
        aria-hidden="true"
        className={cn(
          "flex shrink-0 items-center justify-center rounded-full border border-input",
          size.variant === "compact" ? "size-3.5" : "size-4"
        )}
      >
        <Radio.Indicator
          render={
            <motion.span
              layoutId={reduced ? undefined : "radio-dot"}
              transition={
                reduced ? motionPresets.snap : motionPresets.activeIndicator
              }
            />
          }
          className={cn(
            "relative z-10 rounded-full bg-foreground",
            size.variant === "compact" ? "size-[7px]" : "size-2"
          )}
        />
      </span>
      <span className="flex min-w-0 flex-col">
        <span id={`${id}-label`}>{label}</span>
        {description && (
          <span
            id={`${id}-description`}
            className="text-xs text-muted-foreground"
          >
            {description}
          </span>
        )}
      </span>
    </Radio.Root>
  );
};

"use client";

import { mergeProps } from "@base-ui/react/merge-props";
import { useRender } from "@base-ui/react/use-render";
import { useEffect, useRef } from "react";

import { FluidHoverHighlight } from "@/components/ui/fluid-hover-highlight";
import { useFluidHover } from "@/hooks/use-fluid-hover";
import { cn } from "@/lib/utils";

// Only the moving background is shared. Primitives keep ownership of focus,
// selection and keyboard navigation.
export const FluidHoverArea = ({
  itemSelector,
  axis = "y",
  children,
  className,
  render,
  ref,
  ...props
}: useRender.ComponentProps<"div"> & {
  itemSelector: string;
  axis?: "x" | "y" | "xy";
}) => {
  const container = useRef<HTMLDivElement>(null);
  const hover = useFluidHover(container, { axis, gapClick: false });
  const { registerItem } = hover;
  useEffect(() => {
    const element = container.current;
    if (!element) {
      return;
    }
    let items: HTMLElement[] = [];
    const syncItems = () => {
      const next = [...element.querySelectorAll<HTMLElement>(itemSelector)];
      for (
        let index = 0;
        index < Math.max(items.length, next.length);
        index += 1
      ) {
        registerItem(index, next[index] ?? null);
      }
      items = next;
    };
    syncItems();
    const observer = new MutationObserver(syncItems);
    observer.observe(element, { childList: true, subtree: true });
    return () => {
      observer.disconnect();
      for (const [index] of items.entries()) {
        registerItem(index, null);
      }
    };
  }, [children, itemSelector, registerItem]);
  return useRender({
    props: mergeProps(
      {
        ...hover.handlers,
        children: (
          <>
            <FluidHoverHighlight hover={hover} />
            {children}
          </>
        ),
        className: cn("relative isolate", className),
        onKeyDownCapture: () => hover.setActiveIndex(null),
      },
      props
    ),
    ref: [container, ref ?? null],
    render,
  });
};

"use client";
import { AnimatePresence, motion } from "motion/react";
import type { Transition } from "motion/react";

import type { UseFluidHoverReturn } from "@/hooks/use-fluid-hover";
import { useReducedMotion } from "@/hooks/use-reduced-motion";
import { motionPresets, motionTransition, spring } from "@/lib/motion";
import { useShape } from "@/lib/shape-context";
import { cn } from "@/lib/utils";

export const FluidHoverHighlight = ({
  hover,
  hidden = false,
  className,
  transition = spring.fast,
}: {
  hover: UseFluidHoverReturn;
  hidden?: boolean;
  className?: string;
  transition?: Transition | false;
}) => {
  const reduced = useReducedMotion();
  const shape = useShape();
  const rect =
    !hidden && hover.isMeasured && hover.activeIndex !== null
      ? hover.itemRects[hover.activeIndex]
      : null;
  const target = rect
    ? { height: rect.height, width: rect.width, x: rect.left, y: rect.top }
    : {};
  return (
    <AnimatePresence>
      {rect && (
        <motion.div
          key={hover.sessionRef.current}
          aria-hidden="true"
          data-slot="fluid-hover-highlight"
          className={cn(
            "pointer-events-none absolute top-0 left-0 bg-(--fluid-hover)",
            shape,
            className
          )}
          initial={{ ...target, opacity: 0 }}
          animate={{ ...target, opacity: 1 }}
          exit={{ opacity: 0, transition: spring.fast.exit }}
          transition={{
            ...motionTransition(
              transition === false ? motionPresets.snap : transition,
              reduced
            ),
            opacity: motionPresets.fade,
          }}
        />
      )}
    </AnimatePresence>
  );
};

"use client";
import { useCallback, useEffect, useRef, useState } from "react";
import type { MouseEvent, PointerEvent, RefObject } from "react";

export interface ItemRect {
  top: number;
  left: number;
  width: number;
  height: number;
}
export interface UseFluidHoverOptions {
  axis?: "x" | "y" | "xy";
  isItemDisabled?: (element: HTMLElement) => boolean;
  gapClick?: boolean | { maxDistance?: number };
}
export const useFluidHover = <T extends HTMLElement>(
  containerRef: RefObject<T | null>,
  { axis = "y", isItemDisabled, gapClick = true }: UseFluidHoverOptions = {}
) => {
  const items = useRef(new Map<number, HTMLElement>());
  const observer = useRef<ResizeObserver | null>(null);
  const frame = useRef<number | null>(null);
  const point = useRef<{ x: number; y: number } | null>(null);
  const sessionRef = useRef(0);
  const [activeIndex, setActiveIndex] = useState<number | null>(null);
  const [itemRects, setItemRects] = useState<Record<number, ItemRect>>({});
  const [isMeasured, setIsMeasured] = useState(false);
  const disabled = useCallback(
    (element: HTMLElement) =>
      element.matches(":disabled,[aria-disabled=true],[data-disabled]") ||
      element.getClientRects().length === 0 ||
      !!isItemDisabled?.(element),
    [isItemDisabled]
  );
  const measureItems = useCallback(() => {
    const container = containerRef.current;
    if (!container || !container.offsetWidth || !container.offsetHeight) {
      setIsMeasured(false);
      return;
    }
    const bounds = container.getBoundingClientRect();
    const scaleX = bounds.width / container.offsetWidth || 1;
    const scaleY = bounds.height / container.offsetHeight || 1;
    const next: Record<number, ItemRect> = {};
    let nearest: number | null = null;
    let distance = Infinity;
    for (const [index, element] of items.current) {
      if (disabled(element)) {
        continue;
      }
      const rect = element.getBoundingClientRect();
      next[index] = {
        height: rect.height / scaleY,
        left:
          (rect.left - bounds.left) / scaleX +
          container.scrollLeft -
          container.clientLeft,
        top:
          (rect.top - bounds.top) / scaleY +
          container.scrollTop -
          container.clientTop,
        width: rect.width / scaleX,
      };
      if (!point.current) {
        continue;
      }
      const { x, y } = point.current;
      const insideX = x >= rect.left && x <= rect.right;
      const insideY = y >= rect.top && y <= rect.bottom;
      const contains = (axis === "y" || insideX) && (axis === "x" || insideY);
      const dx = x - (rect.left + rect.width / 2);
      const dy = y - (rect.top + rect.height / 2);
      const distances = {
        x: Math.abs(dx),
        xy: Math.hypot(dx, dy),
        y: Math.abs(dy),
      };
      const candidate = contains ? -1 : distances[axis];
      if (candidate < distance) {
        distance = candidate;
        nearest = index;
      }
    }
    setItemRects((previous) =>
      JSON.stringify(previous) === JSON.stringify(next) ? previous : next
    );
    setIsMeasured(true);
    if (point.current) {
      setActiveIndex(nearest);
    }
  }, [containerRef, axis, disabled]);
  const remeasure = useCallback(() => {
    if (frame.current !== null) {
      return;
    }
    frame.current = requestAnimationFrame(() => {
      frame.current = null;
      measureItems();
    });
  }, [measureItems]);
  const registerItem = useCallback(
    (index: number, element: HTMLElement | null) => {
      const previous = items.current.get(index);
      if (previous === element) {
        return;
      }
      if (previous) {
        observer.current?.unobserve(previous);
      }
      if (element) {
        items.current.set(index, element);
        observer.current?.observe(element);
      } else {
        items.current.delete(index);
      }
      remeasure();
    },
    [remeasure]
  );
  useEffect(() => {
    const container = containerRef.current;
    if (!container) {
      return;
    }
    observer.current = new ResizeObserver(remeasure);
    observer.current.observe(container);
    for (const element of items.current.values()) {
      observer.current.observe(element);
    }
    const mutation = new MutationObserver(remeasure);
    mutation.observe(container, {
      characterData: true,
      childList: true,
      subtree: true,
    });
    container.addEventListener("scroll", remeasure, { passive: true });
    remeasure();
    return () => {
      observer.current?.disconnect();
      observer.current = null;
      mutation.disconnect();
      container.removeEventListener("scroll", remeasure);
      if (frame.current !== null) {
        cancelAnimationFrame(frame.current);
        frame.current = null;
      }
    };
  }, [containerRef, remeasure]);
  useEffect(() => {
    const element =
      activeIndex === null ? null : items.current.get(activeIndex);
    if (!element) {
      return;
    }
    element.dataset.fluidHoverActive = "";
    return () => {
      delete element.dataset.fluidHoverActive;
    };
  }, [activeIndex]);
  const onPointerMove = (event: PointerEvent) => {
    if (event.pointerType !== "touch") {
      point.current = { x: event.clientX, y: event.clientY };
      remeasure();
    }
  };
  const onPointerLeave = () => {
    point.current = null;
    setActiveIndex(null);
  };
  const onClick = (event: MouseEvent) => {
    if (
      !gapClick ||
      !point.current ||
      event.defaultPrevented ||
      !(event.target instanceof Element)
    ) {
      return;
    }
    for (const element of items.current.values()) {
      if (element.contains(event.target)) {
        return;
      }
    }
    if (
      event.target.closest(
        "button,a,input,textarea,select,[contenteditable],[role=button]"
      )
    ) {
      return;
    }
    const element =
      activeIndex === null ? null : items.current.get(activeIndex);
    if (!element || disabled(element)) {
      return;
    }
    const rect = element.getBoundingClientRect();
    const distance = Math.hypot(
      Math.max(rect.left - event.clientX, 0, event.clientX - rect.right),
      Math.max(rect.top - event.clientY, 0, event.clientY - rect.bottom)
    );
    if (
      typeof gapClick === "object" &&
      distance > (gapClick.maxDistance ?? Infinity)
    ) {
      return;
    }
    const activator = element.matches(
      "button,a,[role=tab],[role=menuitem],[role=option]"
    )
      ? element
      : element.querySelector<HTMLElement>("button,a,[role=button]");
    activator?.click();
  };
  return {
    activeIndex,
    handlers: {
      onClick,
      onPointerCancel: onPointerLeave,
      onPointerEnter: (event: PointerEvent) => {
        if (event.pointerType !== "touch") {
          sessionRef.current += 1;
          onPointerMove(event);
        }
      },
      onPointerLeave,
      onPointerMove,
    },
    isMeasured,
    itemRects,
    measureItems,
    registerItem,
    remeasure,
    sessionRef,
    setActiveIndex,
  };
};
export type UseFluidHoverReturn = ReturnType<typeof useFluidHover>;

import { useEffect, useState } from "react";

export const useMediaQuery = (query: string) => {
  const [value, setValue] = useState(false);

  useEffect(() => {
    const onChange = (event: MediaQueryListEvent) => {
      setValue(event.matches);
    };

    const result = matchMedia(query);
    result.addEventListener("change", onChange);
    setValue(result.matches);

    return () => result.removeEventListener("change", onChange);
  }, [query]);

  return value;
};

"use client";

import { useMediaQuery } from "@/hooks/use-media-query";

/** False during SSR and the first hydration render; subscribes after mounting. */
export const useReducedMotion = () =>
  useMediaQuery("(prefers-reduced-motion: reduce)");

import type { Transition } from "motion/react";

// Base UI owns presence; CSS consumers use the same timing ladder as Motion.
export const motionClasses = {
  moderate:
    "duration-(--motion-moderate) data-[state=closed]:duration-(--motion-exit-moderate) motion-reduce:animate-none",
  slow: "duration-(--motion-slow) data-[state=closed]:duration-(--motion-exit-slow) motion-reduce:animate-none",
};

// Fluid Functionalism's timing ladder: quick feedback, precise panels, larger moves.
export const spring = {
  fast: { bounce: 0, duration: 0.08, exit: { duration: 0.06 }, type: "spring" },
  moderate: {
    bounce: 0,
    duration: 0.16,
    exit: { duration: 0.12 },
    type: "spring",
  },
  slow: {
    bounce: 0.12,
    duration: 0.24,
    exit: { duration: 0.16 },
    type: "spring",
  },
} as const;

export const motionPresets = {
  activeIndicator: spring.moderate,
  enter: {
    animate: { opacity: 1, scale: 1 },
    initial: { opacity: 0, scale: 0.95 },
    transition: spring.moderate,
  },
  exit: { opacity: 0, scale: 0.95, transition: spring.moderate.exit },
  fade: { duration: spring.fast.duration },
  hover: spring.fast,
  layout: spring.moderate,
  snap: { duration: 0 },
} satisfies Record<string, unknown>;

export const motionTransition = (
  transition: Transition,
  reduced: boolean
): Transition =>
  reduced ? { duration: 0, opacity: motionPresets.fade } : transition;

"use client";

import { createContext, useContext } from "react";
import type { ReactNode } from "react";

export type ShapeVariant = "rounded" | "pill";
const ShapeContext = createContext<ShapeVariant>("rounded");
export const shapeMap = {
  pill: "rounded-[20px]",
  rounded: "rounded-lg",
} as const;
export const ShapeProvider = ({
  shape,
  children,
}: {
  shape: ShapeVariant;
  children: ReactNode;
}) => <ShapeContext.Provider value={shape}>{children}</ShapeContext.Provider>;
export const useShape = (override?: ShapeVariant) => {
  const inherited = useContext(ShapeContext);
  return shapeMap[override ?? inherited];
};

"use client";

import { createContext, useContext } from "react";
import type { ReactNode } from "react";

export type SizeVariant = "default" | "compact";
const SizeContext = createContext<SizeVariant>("default");
export const sizeMap = {
  compact: {
    control: "h-7",
    controlHeight: 28,
    gap: "gap-1",
    icon: 14,
    iconClass: "[&_svg:not([class*='size-'])]:size-3.5",
    px: "px-2.5",
    text: "text-xs",
    variant: "compact",
  },
  default: {
    control: "h-9",
    controlHeight: 36,
    gap: "gap-2",
    icon: 16,
    iconClass: "[&_svg:not([class*='size-'])]:size-4",
    px: "px-3",
    text: "text-[13px]",
    variant: "default",
  },
} as const;
export const SizeProvider = ({
  size,
  children,
}: {
  size: SizeVariant;
  children: ReactNode;
}) => <SizeContext.Provider value={size}>{children}</SizeContext.Provider>;
export const useSizeVariant = (override?: SizeVariant) => {
  const inherited = useContext(SizeContext);
  return override ?? inherited;
};
export const useSize = (override?: SizeVariant) =>
  sizeMap[useSizeVariant(override)];
